mapper.select:
SELECT t.id, s.data_source_id AS dataSourceId, s.database_name AS databaseName, s.schema_name AS schemaName, t.table_name AS tableName, t.table_type AS tableType, t.comment FROM table_meta_cache t INNER JOIN schema_meta_cache s ON t.schema_cache_id = s.id WHERE s.data_source_id = #{dataSourceId} AND s.database_name = #{databaseName} AND s.user_id = #{userId}
AND s.schema_name = #{schemaName}
AND s.schema_name IS NULL
ORDER BY t.table_name
